const rows = $input.all().map(i => i.json);
const weekAgo = Date.now() - 7 * 24 * 60 * 60 * 1000;
const week = rows.filter(r => new Date(r.created_at).getTime() >= weekAgo);

const total = week.length;
const hot = week.filter(r => r.score === 'hot').length;
const warm = week.filter(r => r.score === 'warm').length;
const cold = week.filter(r => r.score === 'cold').length;
const pipeline = week.reduce((s, r) => s + Number(r.estimate_pkr || 0), 0);
const fu1 = week.filter(r => r.status === 'followup1').length;
const fu2 = week.filter(r => r.status === 'followup2').length;
const money = 'Rs ' + pipeline.toLocaleString('en-US');

const box = (label, value, color) =>
  `<td style="padding:14px;text-align:center;background:${color};color:#fff;border-radius:8px">
     <div style="font-size:26px;font-weight:bold">${value}</div>
     <div style="font-size:12px">${label}</div></td>`;

const html = `
<div style="font-family:Arial,sans-serif;max-width:560px;margin:auto;border:1px solid #e0e0e0;border-radius:10px;overflow:hidden">
  <div style="background:#f59e0b;padding:18px;color:#fff">
    <h2 style="margin:0">SolarFlow Weekly Report</h2>
    <div style="font-size:13px">Last 7 days</div>
  </div>
  <div style="padding:18px">
    <table width="100%" cellspacing="8"><tr>
      ${box('Total Leads', total, '#2563eb')}
      ${box('Hot', hot, '#dc2626')}
      ${box('Warm', warm, '#f97316')}
      ${box('Cold', cold, '#6b7280')}
    </tr></table>
    <h3 style="margin-bottom:6px">Quote Value</h3>
    <div style="font-size:24px;font-weight:bold;color:#16a34a">${money}</div>
    <h3 style="margin-bottom:6px">Follow-ups</h3>
    <table width="100%" cellpadding="8" style="border-collapse:collapse">
      <tr style="background:#f3f4f6"><td>Follow-up 1 sent</td><td align="right"><b>${fu1}</b></td></tr>
      <tr><td>Follow-up 2 sent</td><td align="right"><b>${fu2}</b></td></tr>
    </table>
  </div>
  <div style="background:#f9fafb;padding:10px;text-align:center;font-size:11px;color:#888">
    Automated by SolarFlow (n8n)
  </div>
</div>`;

return [{ json: { total, hot, warm, cold, pipeline, fu1, fu2, html } }];
